#!/usr/bin/env node
/**
 * Generate the platform token files from design/tokens.json.
 *
 *   node scripts/tokens.mjs           write the generated files
 *   node scripts/tokens.mjs --check   fail when a generated file is stale
 *
 * The web core palette lives in `apps/web/src/tokens.generated.css` (imported by
 * `themes.css`); the Swift block is written between markers inside
 * `MissionTheme.swift`; the Android palette is `DesignTokens.kt`. Edit the JSON,
 * never the generated regions.
 */
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const check = process.argv.includes('--check')
const tokens = JSON.parse(readFileSync(join(root, 'design', 'tokens.json'), 'utf8'))

const webPath = join(root, 'apps/web/src/tokens.generated.css')
const swiftPath = join(root, 'apps/ios/MissionControl/UI/MissionTheme.swift')
const kotlinPath = join(
  root,
  'apps/android/app/src/main/java/org/nighthawklabs/missioncontrol/ui/theme/DesignTokens.kt',
)

const ROLE_ORDER = Object.keys(tokens.roles)
const VARIANTS = ['light', 'dark', 'lightContrast', 'darkContrast']
const errors = []

for (const role of ROLE_ORDER) {
  for (const variant of VARIANTS) {
    const value = tokens.roles[role]?.[variant]
    if (!/^#[0-9A-Fa-f]{6}$/.test(value ?? '')) {
      errors.push(`design/tokens.json: ${role}.${variant} must be a #RRGGBB value`)
    }
  }
  if (!tokens.web?.[role]) {
    errors.push(`design/tokens.json: no web variable mapping for ${role}`)
  }
}
if (errors.length) {
  console.error(errors.join('\n'))
  process.exit(1)
}

const cssVar = (role) =>
  role === 'graphCanvas' ? '--theme-graph-canvas' : `--theme-flat-${tokens.web[role]}`
const cssBlock = (variant) =>
  ROLE_ORDER.map((role) => `  ${cssVar(role)}: ${tokens.roles[role][variant].toLowerCase()};`).join('\n')

const css = `/* Generated by scripts/tokens.mjs from design/tokens.json. Do not edit. */
:root,
:root[data-theme='dark'] {
${cssBlock('dark')}
}

:root[data-theme='light'] {
${cssBlock('light')}
}
`

const swiftName = (role) => role
const swiftBlock = [
  '    // BEGIN GENERATED TOKENS (design/tokens.json)',
  ...ROLE_ORDER.map((role) => {
    const value = tokens.roles[role]
    return `    static let ${swiftName(role)} = adaptive(light: 0x${value.light.slice(1)}, dark: 0x${value.dark.slice(1)}, lightContrast: 0x${value.lightContrast.slice(1)}, darkContrast: 0x${value.darkContrast.slice(1)})`
  }),
  '    // END GENERATED TOKENS',
].join('\n')

const kotlin = `// Generated by scripts/tokens.mjs from design/tokens.json. Do not edit.
package org.nighthawklabs.missioncontrol.ui.theme

import androidx.compose.ui.graphics.Color

object DesignTokens {
${ROLE_ORDER.flatMap((role) =>
  VARIANTS.map((variant) => {
    const name = `${role}${variant[0].toUpperCase()}${variant.slice(1)}`
    return `    val ${name} = Color(0xFF${tokens.roles[role][variant].slice(1).toUpperCase()})`
  }),
).join('\n')}
}
`

const begin = '    // BEGIN GENERATED TOKENS (design/tokens.json)'
const end = '    // END GENERATED TOKENS'

function applySwift(source) {
  const start = source.indexOf(begin)
  const finish = source.indexOf(end)
  if (start < 0 || finish < 0 || finish < start) {
    throw new Error(`${swiftPath}: generated-token markers are missing`)
  }
  return source.slice(0, start) + swiftBlock + source.slice(finish + end.length)
}

function read(path) {
  return existsSync(path) ? readFileSync(path, 'utf8') : null
}

function report(label, path, current, next) {
  if (current === next) return
  if (check) {
    errors.push(`${label} is stale; run: node scripts/tokens.mjs`)
  } else {
    writeFileSync(path, next)
    console.log(`wrote ${label}`)
  }
}

report('apps/web/src/tokens.generated.css', webPath, read(webPath), css)
report(
  'apps/android/app/src/main/java/org/nighthawklabs/missioncontrol/ui/theme/DesignTokens.kt',
  kotlinPath,
  read(kotlinPath),
  kotlin,
)

try {
  const current = read(swiftPath)
  if (current === null) {
    errors.push(`${swiftPath} is missing`)
  } else {
    report('apps/ios/MissionControl/UI/MissionTheme.swift', swiftPath, current, applySwift(current))
  }
} catch (error) {
  errors.push(error.message)
}

if (errors.length) {
  console.error(errors.join('\n'))
  process.exit(1)
}
if (!check) console.log('tokens are up to date')
